```vue
<!-- ./frontend/app/components/content/RichTextEditor.vue -->
<script setup>
import { useEditor, EditorContent } from '@tiptap/vue-3'
import StarterKit from '@tiptap/starter-kit'
import Link from '@tiptap/extension-link'
import Underline from '@tiptap/extension-underline'
import Placeholder from '@tiptap/extension-placeholder'

const model = defineModel({
  type: String,
  default: '',
})

const props = defineProps({
  placeholder: {
    type: String,
    default: 'Введите текст...',
  },
  minHeight: {
    type: String,
    default: '24rem',
  },
  disabled: {
    type: Boolean,
    default: false,
  },
})

const editor = useEditor({
  content: model.value,

  editable: !props.disabled,

  extensions: [
    StarterKit.configure({
      heading: {
        levels: [2, 3, 4],
      },
    }),

    Underline,

    Link.configure({
      openOnClick: false,
      autolink: true,
      linkOnPaste: true,
      HTMLAttributes: {
        rel: 'noopener noreferrer',
        target: '_blank',
      },
    }),

    Placeholder.configure({
      placeholder: props.placeholder,
    }),
  ],

  onUpdate({ editor: currentEditor }) {
    model.value = currentEditor.getHTML()
  },
})

watch(
  () => model.value,
  (newValue) => {
    if (!editor.value) return

    const currentValue = editor.value.getHTML()

    if (newValue !== currentValue) {
      editor.value.commands.setContent(
        newValue || '',
        {
          emitUpdate: false,
        },
      )
    }
  },
)

watch(
  () => props.disabled,
  (value) => {
    editor.value?.setEditable(!value)
  },
)

function setLink() {
  if (!editor.value) return

  const previousUrl =
    editor.value.getAttributes('link').href || ''

  const url = window.prompt(
    'Введите адрес ссылки',
    previousUrl,
  )

  if (url === null) return

  if (!url.trim()) {
    editor.value
      .chain()
      .focus()
      .extendMarkRange('link')
      .unsetLink()
      .run()

    return
  }

  editor.value
    .chain()
    .focus()
    .extendMarkRange('link')
    .setLink({
      href: url.trim(),
    })
    .run()
}

function clearFormatting() {
  editor.value
    ?.chain()
    .focus()
    .clearNodes()
    .unsetAllMarks()
    .run()
}

onBeforeUnmount(() => {
  editor.value?.destroy()
})
</script>

<template>
  <div
    class="border-base-300 bg-base-100 overflow-hidden rounded-2xl border"
    :class="{
      'opacity-60': disabled,
    }"
  >
