<script setup>
const model = defineModel({
  type: Array,
  default: () => [],
})

defineProps({
  tags: {
    type: Array,
    default: () => [],
  },
  loading: {
    type: Boolean,
    default: false,
  },
})

function isSelected(tagId) {
  return model.value.includes(tagId)
}

function toggle(tagId) {
  if (isSelected(tagId)) {
    model.value = model.value.filter(
      (currentId) => currentId !== tagId,
    )
  } else {
    model.value = [
      ...model.value,
      tagId,
    ]
  }
}
</script>

<template>
  <div>
    <div
      v-if="loading"
      class="flex items-center gap-2 py-3"
    >
