<script setup>
const props = defineProps({
  initialValue: {
    type: Object,
    default: null,
  },
  saving: {
    type: Boolean,
    default: false,
  },
  submitLabel: {
    type: String,
    default: 'Сохранить статью',
  },
})

const emit = defineEmits([
  'submit',
  'cancel',
])

const { $api } = useNuxtApp()

const tags = ref([])
const loadingTags = ref(false)

const previewOpen = ref(false)
const errorMessage = ref('')

const form = reactive({
  title: '',
  content: '',
  tag_ids: [],
  pro_content: true,
})

function applyInitialValue(value) {
  if (!value) return

  form.title = value.title || ''
  form.content = value.content || ''
  form.tag_ids = (value.tags || []).map(
    (tag) => tag.id,
  )
  form.pro_content = Boolean(value.pro_content)
}

async function loadTags() {
  loadingTags.value = true

  try {
    tags.value = await $api('/api/v1/tags')
  } finally {
    loadingTags.value = false
  }
}

function submit() {
  errorMessage.value = ''

  if (!form.title.trim()) {
    errorMessage.value = 'Введите название статьи'
    return
  }

  if (!form.content.trim() || form.content === '<p></p>') {
    errorMessage.value = 'Введите текст статьи'
    return
  }

  emit('submit', {
    title: form.title.trim(),
    content: form.content,
    tag_ids: form.tag_ids,
    pro_content: form.pro_content,
  })
}

watch(
  () => props.initialValue,
  applyInitialValue,
  {
    immediate: true,
  },
)

onMounted(loadTags)
</script>

